B.ab8=new A.bM("Den\xe1r",!1,B.aH0,"St\u0159\xedbrn\xe1 \u0159\xedmsk\xe1 mince velk\xe1 asi jako dne\u0161n\xed desetikoruna. Byla to obvykl\xe1 denn\xed mzda d\u011bln\xedka na vinici \u2013 tedy \u201epen\xedze za jeden den pr\xe1ce\u201c.")
B.azU=s(["peniz","penizi"],t.s)
B.aau=new A.bM("Den\xe1r (pen\xedz)",!0,B.azU,"V Kralick\xe9 \u201epen\xedz\u201c v evangeli\xedch znamen\xe1 den\xe1r \u2013 st\u0159\xedbrnou \u0159\xedmskou minci s c\xedsa\u0159ov\xfdm obrazem, denn\xed mzdu d\u011bln\xedka.")
B.ao9=s(["drachm*","gros","grose","grosu","grosi","grosem"],t.s)
B.aaz=new A.bM("Drachma (gro\u0161)",!1,B.ao9,"\u0158eck\xe1 st\u0159\xedbrn\xe1 mince v hodnot\u011b zhruba jednoho den\xe1ru \u2013 asi denn\xed mzda. Ztracen\xfd gro\u0161 v Lk 15 byl pro chudou \u017eenu velk\xe1 ztr\xe1ta.")
B.atB=s(["hrivn*"],t.s)
B.aaS=new A.bM("H\u0159ivna",!1,B.atB,"Velk\xe1 jednotka v\xe1hy a pen\u011bz. Podle p\u0159ekladu ozna\u010duje bu\u010f minu (asi 100 den\xe1r\u016f, tedy t\u0159i a\u017e \u010dty\u0159i m\u011bs\xedce pr\xe1ce), nebo talent (p\u0159es 6000 den\xe1r\u016f \u2013 mzda za mnoho let).")
B.amc=s(["talent*"],t.s)
B.aaU=new A.bM("Talent",!1,B.amc,"Nejv\u011bt\u0161\xed jednotka v\xe1hy a pen\u011bz: asi 30\u201340 kg st\u0159\xedbra, tedy zhruba 6000 den\xe1r\u016f \u2013 mzda za 15\u201320 let pr\xe1ce. Z podobenstv\xed o talentech poch\xe1z\xed i dne\u0161n\xed slovo \u201etalent\u201c pro nad\xe1n\xed.")
B.axq=s(["mina","miny","minu","minami"],t.s)
B.aax=new A.bM("Mina",!1,B.axq,"Jednotka v\xe1hy a pen\u011bz: asi p\u016fl kila st\u0159\xedbra, 100 den\xe1r\u016f \u2013 mzda za t\u0159i a\u017e \u010dty\u0159i m\u011bs\xedce.")
B.aiO=s(["sekel*","sekl*","sikl*"],t.s)
B.aaj=new A.bM("\u0160ekel",!1,B.aiO,"Z\xe1kladn\xed jednotka v\xe1hy (asi 11 g). Ve Star\xe9m z\xe1kon\u011b se neplatilo mincemi, ale odv\xe1\u017een\xfdm st\u0159\xedbrem \u2013 proto \u201e\u0161ekel\u201c znamen\xe1 v\xe1hu i cenu.")
B.aGS=s(["sarty","sart","sartu","halir","halire","lepto*","kodrant*"],t.s)
B.aaY=new A.bM("Nejmen\u0161\xed mince",!1,B.aGS,"Lept\xf3n byla nejmen\u0161\xed m\u011bd\u011bn\xe1 mince v ob\u011bhu \u2013 asi 1/128 den\xe1ru. Dv\u011b takov\xe9 mince vdovy byly prakticky nic, a p\u0159ece podle Je\u017e\xed\u0161e dala nejv\xedc.")
B.agV=s(["stater*"],t.s)
B.aai=new A.bM("Stat\xe9r",!1,B.agV,"St\u0159\xedbrn\xe1 mince v hodnot\u011b \u010dty\u0159 drachem \u2013 p\u0159esn\u011b chr\xe1mov\xe1 da\u0148 za dva lidi (Petra a Je\u017e\xed\u0161e, Mt 17,27).")
B.apH=s(["clo","cla","clu","cle","celnic*"],t.s)
B.aaE=new A.bM("Clo a dan\u011b",!1,B.apH,"\u0158\xedman\xe9 pronaj\xedmali v\xfdb\u011br cel a dan\xed m\xedstn\xedm lidem. Ti museli odv\xe9st pevnou \u010d\xe1stku a co vybrali nav\xedc, si nechali \u2013 proto byli celn\xedci pova\u017eov\xe1ni za zlod\u011bje a zr\xe1dce.")
B.aoF=s(["loket","lokte","loktu","lokty","loktech","loktu","loktum"],t.s)
