B.aA3=s(["pid","pidi","pidem"],t.s)
B.aaw=new A.bM("P\xed\u010f",!1,B.aA3,"Rozp\u011bt\xed rozta\u017een\xe9 dlan\u011b od palce po mal\xed\u010dek \u2013 asi 22 cm, p\u016fl lokte.")
B.aqW=s(["efa","efy","efu","efi","efou"],t.s)
B.ab4=new A.bM("Efa",!1,B.aqW,"Dut\xe1 m\xedra na obil\xed a mouku, asi 22 litr\u016f \u2013 zhruba velk\xfd kbel\xedk. Desetina efy (omer) byla denn\xed d\xe1vka many na osobu.")
B.alo=s(["chomer*","chomeru"],t.s)
B.abb=new A.bM("Chomer a k\xf3r",!1,B.alo,"Velk\xe1 m\xedra na obil\xed \u2013 \u201eosl\xed n\xe1klad\u201c, asi 220 litr\u016f. Odpov\xedd\xe1 deseti ef\xe1m.")
B.apy=s(["bat","batu","batu","batech"],t.s)
B.aaZ=new A.bM("Bat",!1,B.apy,"M\xedra na tekutiny (olej, v\xedno), asi 22 litr\u016f \u2013 stejn\u011b jako efa u obil\xed.")
B.auE=s(["hin","hinu"],t.s)
B.ab_=new A.bM("Hin",!1,B.auE,"Men\u0161\xed m\xedra na tekutiny, asi 3,5\u20134 litry.")
B.ams=s(["stadi*"],t.s)
B.aaf=new A.bM("Stadium",!1,B.ams,"\u0158eck\xe1 d\xe9lkov\xe1 m\xedra, asi 185 metr\u016f \u2013 d\xe9lka b\u011b\u017eeck\xe9 dr\xe1hy na stadionu. Odtud dne\u0161n\xed slovo stadion.")
B.ahc=s(["farize*","farizej*"],t.s)
B.ab7=new A.bM("Farizeov\xe9",!1,B.ahc,"Zbo\u017en\xe9 hnut\xed laik\u016f, kte\u0159\xed cht\u011bli zachov\xe1vat Z\xe1kon v ka\u017edodenn\xedm \u017eivot\u011b \u2013 p\u0159i j\xeddle, pr\xe1ci i sabatu. Lid si jich v\xe1\u017eil. Je\u017e\xed\u0161 je kritizoval, kdy\u017e se pravidla stala d\u016fle\u017eit\u011bj\u0161\xed ne\u017e milosrdenstv\xed.")
B.ag9=s(["saduce*","saducej*"],t.s)
B.aac=new A.bM("Saduceov\xe9",!1,B.ag9,"Kn\u011b\u017esk\xe1 aristokracie kolem chr\xe1mu, spolupracovala s \u0158\xedmany. Uzn\xe1vali jen p\u011bt knih Moj\u017e\xed\u0161ov\xfdch a nev\u011b\u0159ili ve vzk\u0159\xed\u0161en\xed ani v and\u011bly.")
B.amM=s(["zakonik*","zakonic*"],t.s)
B.abe=new A.bM("Z\xe1kon\xedci",!1,B.amM,"Znalci a vyklada\u010di Z\xe1kona \u2013 u\u010ditel\xe9 a \u201epr\xe1vn\xedci\u201c sv\xe9 doby. Opisovali P\xedsmo a rozhodovali, jak se m\xe1 p\u0159ik\xe1z\xe1n\xed v praxi dodr\u017eovat.")
B.ag4=s(["publikan*","celnik*"],t.s)
B.aah=new A.bM("Celn\xedci (publik\xe1ni)",!1,B.ag4,"V\xfdb\u011br\u010d\xed cel a dan\xed pro \u0158\xedmany. \u010casto vyb\xedrali v\xedc, ne\u017e m\u011bli \u2013 lid je pokl\xe1dal za podvodn\xedky a kolaboranty. Je\u017e\xed\u0161 s nimi p\u0159esto jedl a jednoho (Matou\u0161e) povolal za u\u010dedn\xedka.")
B.auF=s(["levit*"],t.s)
B.aaF=new A.bM("Levit\xe9",!1,B.auF,"Potomci L\xe9viho, kmene ur\u010den\xe9ho ke slu\u017eb\u011b ve svatyni. Pom\xe1hali kn\u011b\u017e\xedm, starali se o chr\xe1m, zp\u011bv a str\xe1\u017e. Nedostali vlastn\xed \xfazem\xed, \u017eili z des\xe1tk\u016f.")
B.ajp=s(["samar*","samaritan*"],t.s)
B.ab9=new A.bM("Sama\u0159\xed a Samarit\xe1ni",!1,B.ajp,"Obyvatel\xe9 st\u0159edn\xed \u010d\xe1sti zem\u011b, potomci Izraelc\u016f sm\xed\u0161en\xfdch s jin\xfdmi n\xe1rody. Uct\xedvali Boha na ho\u0159e Gerizim a uzn\xe1vali jen T\xf3ru. \u017did\xe9 a Samarit\xe1ni se navz\xe1jem nesn\xe1\u0161eli \u2013 proto byl \u201emilosrdn\xfd Samarit\xe1n\u201c tak \u0161okuj\xedc\xed.")
B.avz=s(["velerad*","sanhedr*"],t.s)
B.abd=new A.bM("Velerada",!1,B.avz,"Nejvy\u0161\u0161\xed \u017eidovsk\xfd soud v Jeruzal\xe9m\u011b \u2013 71 \u010dlen\u016f v \u010dele s velekn\u011bzem. Za \u0158\xedman\u016f rozhodovala o n\xe1bo\u017eensk\xfdch v\u011bcech, ale trest smrti vyn\xe9st nesm\u011bla.")
B.ang=s(["velekn*"],t.s)
B.aan=new A.bM("Velekn\u011bz",!1,B.ang,"Nejvy\u0161\u0161\xed kn\u011bz Izraele. Jen on sm\u011bl jednou za rok, o Dni sm\xed\u0159en\xed, vstoupit do velesvatyn\u011b. Za Je\u017e\xed\u0161e \xfa\u0159ad obsazovali \u0158\xedman\xe9 a Herodes.")
B.ao6=s(["setnik*"],t.s)
B.ab3=new A.bM("Setn\xedk",!1,B.ao6,"\u0158\xedmsk\xfd d\u016fstojn\xedk vel\xedc\xed asi stovce voj\xe1k\u016f (centurio). Setn\xedci jsou v Nov\xe9m z\xe1kon\u011b \u010dasto vyl\xed\u010deni kladn\u011b \u2013 jeden z nich vyznal pod k\u0159\xed\u017eem: \u201eTento byl Syn Bo\u017e\xed.\u201c")
B.avN=s(["prokurator*","mistodrzi*"],t.s)
B.abl=new A.bM("M\xedstodr\u017eitel",!1,B.avN,"\u0158\xedmsk\xfd spr\xe1vce provincie (Pil\xe1t v Judsku). M\u011bl vojsko, vyb\xedral dan\u011b a jako jedin\xfd mohl vyn\xe9st rozsudek smrti.")
B.amD=s(["ctvrtak*","tetrarch*"],t.s)
B.ab5=new A.bM("Tetrarcha (\u010dtvrt\xe1k)",!1,B.amD,"Doslova \u201evl\xe1dce \u010dtvrtiny\u201c \u2013 men\u0161\xed panovn\xedk z\xe1visl\xfd na \u0158\xedmu. Herodes Antipas, kter\xfd dal popravit Jana K\u0159titele, byl tetrarchou Galileje.")
B.aGJ=s(["vdov*","sirot*"],t.s)
B.abf=new A.bM("Vdovy a sirotci",!1,B.aGJ,"Ve spole\u010dnosti bez soci\xe1ln\xedho syst\xe9mu byli nejzraniteln\u011bj\u0161\xed: nem\u011bli mu\u017ee ani otce, kter\xfd by je \u017eivil a h\xe1jil. Z\xe1kon i proroci proto opakovan\u011b volaj\xed po jejich ochran\u011b.")
B.ahP=s(["otrok*","otrokyn*"],t.s)
B.aaG=new A.bM("Otroci",!1,B.ahP,"Otroctv\xed bylo ve starov\u011bku b\u011b\u017en\xe9 \u2013 z dluh\u016f, v\xe1lek nebo narozen\xedm. Izraelsk\xfd z\xe1kon ho omezoval (propu\u0161t\u011bn\xed po \u0161esti letech), v \u0159\xedmsk\xe9m sv\u011bt\u011b tvo\u0159ili otroci velkou \u010d\xe1st obyvatel.")
B.aAU=s(["pastyr*","pastucha*"],t.s)
B.aaT=new A.bM("Past\xfd\u0159",!1,B.aAU,"Past\xfd\u0159 vodil ovce na pastvu, hledal vodu a v noci je chr\xe1nil p\u0159ed \u0161elmami a zlod\u011bji. Ovce znaly jeho hlas. Proto se \u201epast\xfd\u0159\u201c stal obrazem kr\xe1le i Boha.")
B.akN=s(["tesar*"],t.s)
B.aaR=new A.bM("Tesa\u0159",!1,B.akN,"\u0158eck\xe9 slovo tekt\xf3n znamen\xe1 \u0159emesln\xedka, kter\xfd pracuje se d\u0159evem i kamenem \u2013 sp\xed\u0161 \u201estavitel\u201c. Je\u017e\xed\u0161 i Josef tak \u017eivili rodinu.")
B.agm=s(["sabat*","sobot*"],t.s)
B.abk=new A.bM("Sabat (sobota)",!1,B.agm,"Sedm\xfd den t\xfddne, den odpo\u010dinku od p\xe1te\u010dn\xedho do sobotn\xedho ve\u010dera. Nesm\u011blo se pracovat ani cestovat d\xe1l ne\u017e asi kilometr. P\u0159ipom\xednal stvo\u0159en\xed i vysvobozen\xed z otroctv\xed.")
B.axJ=s(["velikonoc*","pesach*","fase","fasy","fasu"],t.s)
B.aaC=new A.bM("Pesach (Velikonoce)",!1,B.axJ,"Sv\xe1tek vysvobozen\xed z Egypta. Ka\u017ed\xe1 rodina jedla ber\xe1nka, nekva\u0161en\xfd chl\xe9b a ho\u0159k\xe9 byliny a vypr\xe1v\u011bla p\u0159\xedb\u011bh exodu. Do Jeruzal\xe9ma tehdy p\u0159i\u0161ly statis\xedce poutn\xedk\u016f.")
B.ao1=s(["letnic*"],t.s)
B.ab1=new A.bM("Letnice",!1,B.ao1,"Sv\xe1tek \u017en\xed pades\xe1t dn\xed po Pesachu (\u0159ecky Pent\xe9kost\xe9 \u2013 \u201epades\xe1t\xfd\u201c). Do chr\xe1mu se nesly prvn\xed chleby z nov\xe9 \xfarody.")
B.ajA=s(["nekvasen*","presnic*","presnych","presny"],t.s)
B.aaq=new A.bM("Nekva\u0161en\xfd chl\xe9b",!1,B.ajA,"Ploch\xfd chl\xe9b bez kvasu, upe\u010den\xfd narychlo. O Pesachu p\u0159ipom\xednal, \u017ee Izrael odch\xe1zel z Egypta ve sp\u011bchu a t\u011bsto nestihlo vykynout.")
B.afN=s(["kvas","kvasu","kvasem","kvasne","kvasny"],t.s)
B.aao=new A.bM("Kvas",!1,B.afN,"Kousek star\xe9ho zkva\u0161en\xe9ho t\u011bsta, kter\xfd se p\u0159id\xe1val do nov\xe9ho. Mal\xe9 mno\u017estv\xed prokvas\xed v\u0161echno \u2013 proto je kvas obrazem tich\xe9ho r\u016fstu (Bo\u017e\xed kr\xe1lovstv\xed) i \u0161\xed\u0159en\xed zla.")
B.akT=s(["obriz*","obrez*"],t.s)
B.aaA=new A.bM("Ob\u0159\xedzka",!1,B.akT,"Znamen\xed smlouvy s Abrahamem, prov\xe1d\u011bn\xe9 chlapc\u016fm osm\xfd den po narozen\xed. V prvn\xed c\xedrkvi se vedl velk\xfd spor, zda mus\xed b\xfdt ob\u0159ez\xe1ni i pohan\xe9 (Sk 15).")
B.ahY=s(["desatek","desatk*","desatky"],t.s)
B.aaQ=new A.bM("Des\xe1tek",!1,B.ahY,"Desetina \xfarody a st\xe1da odevzd\xe1van\xe1 Bohu \u2013 na podporu levit\u016f, kn\u011b\u017e\xed, chud\xfdch, vdov a cizinc\u016f.")
B.arW=s(["malomoc*"],t.s)
B.aay=new A.bM("Malomocenstv\xed",!1,B.arW,"Souhrnn\xe9 ozna\u010den\xed pro r\u016fzn\xe9 ko\u017en\xed nemoci (nejen dne\u0161n\xed lepru). Nemocn\xfd musel \u017e\xedt mimo obec a volat \u201ene\u010dist\xfd!\u201c. Je\u017e\xed\u0161\u016fv dotek malomocn\xe9ho byl proto n\u011b\u010d\xedm nev\xeddan\xfdm.")
B.aE4=s(["pomaz*"],t.s)
B.abc=new A.bM("Pomaz\xe1n\xed",!1,B.aE4,"Polit\xed hlavy olejem p\u0159i dosazen\xed kr\xe1le, kn\u011bze nebo proroka \u2013 znamen\xed, \u017ee ho vybral B\u016fh. Hebrejsky \u201epomazan\xfd\u201c = ma\u0161\xedach, Mesi\xe1\u0161; \u0159ecky Christos.")
B.asS=s(["nazir*"],t.s)
B.aam=new A.bM("Naz\xedrsk\xfd slib",!1,B.asS,"Zvl\xe1\u0161tn\xed zasv\u011bcen\xed Bohu: nest\u0159\xedhat si vlasy, nep\xedt v\xedno a nedot\xfdkat se mrtv\xfdch. Naz\xedrem byl nap\u0159\xedklad Samson.")
B.aA0=s(["prvoroz*"],t.s)
B.aaO=new A.bM("Prvorozenstv\xed",!1,B.aA0,"Nejstar\u0161\xed syn dost\xe1val dvojn\xe1sobn\xfd pod\xedl d\u011bdictv\xed a veden\xed rodu. Proto tolik z\xe1le\u017eelo na tom, komu otec po\u017eehn\xe1 (Ezau a J\xe1kob).")
B.ant=s(["paberk*"],t.s)
B.aaP=new A.bM("Pab\u011brkov\xe1n\xed",!1,B.ant,"Z\xe1kon p\u0159ikazoval neskl\xedzet pole a\u017e do kraj\u016f a nechat na n\u011bm klasy, kter\xe9 spadly \u2013 pro chud\xe9, vdovy a cizince. Tak se \u017eivila R\xfat na B\xf3azov\u011b poli.")
B.ahG=s(["zapaln*"],t.s)
B.aaI=new A.bM("Z\xe1paln\xe1 ob\u011b\u0165",!1,B.ahG,"Ob\u011b\u0165, p\u0159i kter\xe9 se cel\xe9 zv\xed\u0159e sp\xe1lilo na olt\xe1\u0159i \u2013 vyjad\u0159ovala \xfapln\xe9 odevzd\xe1n\xed Bohu.")
B.apv=s(["stanek","stanku","stankem","svatostan*"],t.s)
B.abj=new A.bM("St\xe1nek \xfamluvy",!1,B.apv,"P\u0159enosn\xe1 svatyn\u011b z l\xe1tek a k\u016f\u017e\xed, kterou Izrael nosil pou\u0161t\xed. M\u011bl n\xe1dvo\u0159\xed s olt\xe1\u0159em, svatyni se sv\xedcnem a velesvatyni s truhlou smlouvy \u2013 p\u0159edobraz pozd\u011bj\u0161\xedho chr\xe1mu.")
B.aGD=s(["truhl*"],t.s)
B.aaX=new A.bM("Truhla smlouvy",!1,B.aGD,"Pozlacen\xe1 sk\u0159\xed\u0148ka asi 110 \xd7 70 \xd7 70 cm s deskami Desatera. V\xedko se dv\u011bma cheruby (\u201eslitovnice\u201c) bylo m\xedstem Bo\u017e\xed p\u0159\xedtomnosti.")
B.aiG=s(["efod*"],t.s)
B.ab0=new A.bM("Efod",!1,B.aiG,"Kn\u011b\u017esk\xe9 roucho podobn\xe9 z\xe1st\u011b\u0159e, u velekn\u011bze zdoben\xe9 zlatem a drahokamy. Pat\u0159il k n\u011bmu n\xe1prsn\xedk s urim a tumim.")
B.agi=s(["urim*","tumim*"],t.s)
B.aaN=new A.bM("Urim a tumim",!1,B.agi,"P\u0159edm\u011bty v n\xe1prsn\xedku velekn\u011bze, jimi\u017e se hledala Bo\u017e\xed odpov\u011b\u010f ano/ne. Jak p\u0159esn\u011b fungovaly, dnes nev\xedme.")
B.aj3=s(["svicen*","svicn*","menor*"],t.s)
B.aba=new A.bM("Sv\xedcen (menora)",!1,B.aj3,"Sedmiramenn\xfd zlat\xfd sv\xedcen ve svatyni, kde st\xe1le ho\u0159el olej. Dnes je symbolem Izraele.")
B.ajZ=s(["kadid*"],t.s)
B.ab6=new A.bM("Kadidlo",!1,B.ajZ,"Vonn\xe1 prysky\u0159ice ze strom\u016f ji\u017en\xed Ar\xe1bie. Spalovala se na zlat\xe9m olt\xe1\u0159i \u2013 obraz modliteb stoupaj\xedc\xedch k Bohu. Byla velmi drah\xe1.")
B.au0=s(["synagog*"],t.s)
B.abm=new A.bM("Synagoga",!1,B.au0,"Shroma\u017e\u010fovac\xed d\u016fm, kde se \u017did\xe9 v sobotu sch\xe1zeli k modlitb\u011b, \u010dten\xed a v\xfdkladu P\xedsma. Vznikly nejsp\xed\u0161 b\u011bhem vyhnanstv\xed, kdy nebyl chr\xe1m.")
B.avP=s(["jho","jha","jhu","jhem"],t.s)
B.aaD=new A.bM("Jho",!1,B.avP,"D\u0159ev\u011bn\xe9 b\u0159evno na \u0161\xedji dvou vol\u016f, kter\xfdm se t\xe1hl pluh. Obraz pod\u0159\xedzenosti a b\u0159emene \u2013 Je\u017e\xed\u0161 nab\xedz\xed \u201ejho p\u0159\xedjemn\xe9\u201c.")
B.ayy=s(["mlyn*","zernov*"],t.s)
B.aaV=new A.bM("Ml\xfdnsk\xfd k\xe1men",!1,B.ayy,"Obil\xed se mlelo mezi dv\u011bma kameny \u2013 ru\u010dn\u011b (\u017eeny ka\u017ed\xe9 r\xe1no) nebo velk\xfdm kamenem, kter\xfd ot\xe1\u010del osel. Pov\u011bsit n\u011bkomu \u017eernov na krk znamenalo jistou smrt ve vod\u011b.")
B.atx=s(["mlat*","humn*"],t.s)
B.aaM=new A.bM("Mlat (humno)",!1,B.atx,"Udusan\xe9 m\xedsto na kopci, kde se obil\xed ml\xe1tilo a vyhazovalo do v\u011btru: zrno spadlo zp\u011bt, plevy v\xedtr odnesl. Obraz Bo\u017e\xedho soudu.")
B.axe=s(["mech","mechy","mechu","mechach"],t.s)
B.aat=new A.bM("M\u011bchy na v\xedno",!1,B.axe,"V\xedno se uchov\xe1valo v n\xe1dob\xe1ch z koz\xed k\u016f\u017ee. Nov\xe9 v\xedno je\u0161t\u011b kvas\xed a roztahuje se \u2013 star\xfd ztvrdl\xfd m\u011bch by praskl.")
B.aGZ=s(["lis","lisu","lise","lisy","presu"],t.s)
B.aag=new A.bM("Lis na v\xedno",!1,B.aGZ,"Kamenn\xe1 n\xe1dr\u017e, ve kter\xe9 se hrozny \u0161lapaly nohama; \u0161\u0165\xe1va st\xe9kala do ni\u017e\u0161\xed j\xedmky. Obraz radosti ze sklizn\u011b i Bo\u017e\xedho soudu.")
B.anZ=s(["olivov*","oliv*"],t.s)
B.aar=new A.bM("Olivovn\xedk",!1,B.anZ,"Strom, kter\xfd \u017eije stovky let. Olivov\xfd olej slou\u017eil k j\xeddlu, sv\xedcen\xed, l\xe9\u010den\xed i pomaz\xe1n\xed. Getsemane znamen\xe1 \u201elis na olej\u201c.")
B.auj=s(["fikov*","fik","fiky","fiku"],t.s)
B.abi=new A.bM("F\xedkovn\xedk",!1,B.auj,"Jeden z nejcenn\u011bj\u0161\xedch strom\u016f zem\u011b. \u201eSed\u011bt pod sv\xfdm f\xedkovn\xedkem\u201c znamenalo \u017e\xedt v pokoji a bezpe\u010d\xed.")
B.atT=s(["cedr*"],t.s)
B.aae=new A.bM("Cedr",!1,B.atT,"Vysok\xfd vonn\xfd strom z Libanonu, nejcenn\u011bj\u0161\xed stavebn\xed d\u0159evo starov\u011bku. \u0160alomoun z n\u011bj stav\u011bl chr\xe1m i pal\xe1c.")
B.aiW=s(["yzop*","hyzop*","ysop*"],t.s)
B.aal=new A.bM("Yzop",!1,B.aiW,"Drobn\xe1 aromatick\xe1 bylina; svaze\u010dkem se kropilo krv\xed nebo vodou p\u0159i o\u010di\u0161\u0165ov\xe1n\xed. \u201ePokrop m\u011b yzopem\u201c (\u017d 51) = o\u010disti m\u011b.")
B.amx=s(["myrh*"],t.s)
B.aav=new A.bM("Myrha",!1,B.amx,"Vonn\xe1 prysky\u0159ice, drah\xe1 a ho\u0159k\xe1. Pou\u017e\xedvala se k pomaz\xe1n\xed a balzamov\xe1n\xed mrtv\xfdch \u2013 mezi dary mudrc\u016f tak napov\xedd\xe1 Je\u017e\xed\u0161ovu smrt.")
B.akS=s(["nard*"],t.s)
B.ab2=new A.bM("Nardov\xfd olej",!1,B.akS,"Vz\xe1cn\xfd parf\xe9m z rostliny rostouc\xed v Him\xe1laji. L\xe1hev, kterou Marie vylila na Je\u017e\xed\u0161e, m\u011bla cenu ro\u010dn\xed mzdy.")
B.ax2=s(["mana","manu","manou","many"],t.s)
